private void GameOver()
{
    GD.Print("Game Over!");
    // Temporary: respawn instead of showing game over screen
    ResetState();
    var level = ((SceneTree)Engine.GetMainLoop()).CurrentScene;
    if (level is Level currentLevel)
    {
        currentLevel.RespawnPlayer();
    }
}
